import java.util.*;

public class Solution {
    Map<Integer, int[]> memo = new HashMap<>();

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        return dfs(n, firstPlayer, secondPlayer);
    }

    private int[] dfs(int n, int a, int b) {
        int key = (n << 16) | (a << 8) | b;
        if (memo.containsKey(key)) return memo.get(key);
        // If they are matched this round
        if (a + b == n + 1) {
            int[] res = new int[]{1, 1};
            memo.put(key, res);
            return res;
        }
        int pairs = n / 2;
        int mid = (n % 2 == 1) ? (n + 1) / 2 : -1;

        // Determine non-target pairs and deterministic middle winner if exists (and not a or b)
        List<int[]> options = new ArrayList<>(); // each element: {bu_for_u, bu_for_v} bucket indices
        // buckets: 0 = index < a, 1 = a < index < b, 2 = index > b
        int detX = 0, detY = 0; // deterministic contributions to bucket 0 and 1 (excluding targets)
        for (int t = 1; t <= pairs; t++) {
            int u = t;
            int v = n + 1 - t;
            // If pair contains a or b, skip (target wins, deterministic but not counted into x/y)
            if (u == a || v == a || u == b || v == b) {
                continue;
            }
            int bu = bucket(u, a, b);
            int bv = bucket(v, a, b);
            // Add this pair as an option between bu and bv
            options.add(new int[]{bu, bv});
        }
        // middle if exists and not target: deterministic winner
        if (mid != -1 && mid != a && mid != b) {
            int bm = bucket(mid, a, b);
            if (bm == 0) detX++;
            else if (bm == 1) detY++;
            // else bm==2 contributes to right bucket, we don't track explicitly
        }

        // DP over options to find reachable (x,y) counts (winners in bucket0 and bucket1)
        int maxX = a - 1; // max possible winners with index < a
        int maxY = b - a - 1; // max possible winners between a and b
        boolean[][] reachable = new boolean[maxX + 1][maxY + 1];
        if (detX <= maxX && detY <= maxY) reachable[detX][detY] = true;

        for (int[] opt : options) {
            int bu = opt[0], bv = opt[1];
            boolean[][] next = new boolean[maxX + 1][maxY + 1];
            for (int x = 0; x <= maxX; x++) {
                for (int y = 0; y <= maxY; y++) {
                    if (!reachable[x][y]) continue;
                    // choose u winner
                    int nx = x + (bu == 0 ? 1 : 0);
                    int ny = y + (bu == 1 ? 1 : 0);
                    if (nx <= maxX && ny <= maxY) next[nx][ny] = true;
                    // choose v winner
                    nx = x + (bv == 0 ? 1 : 0);
                    ny = y + (bv == 1 ? 1 : 0);
                    if (nx <= maxX && ny <= maxY) next[nx][ny] = true;
                }
            }
            reachable = next;
        }

        int earliest = Integer.MAX_VALUE;
        int latest = Integer.MIN_VALUE;
        int nextN = (n + 1) / 2; // winners count
        // For each reachable (x,y), compute next positions
        for (int x = 0; x <= maxX; x++) {
            for (int y = 0; y <= maxY; y++) {
                if (!reachable[x][y]) continue;
                // number of winners excluding targets among survivors equals nextN - 2
                // but we don't need to verify; DP ensures sums match
                int aNext = 1 + x;
                int bNext = 2 + x + y;
                // validate positions are within [1,nextN] and aNext < bNext
                if (aNext >= bNext || bNext > nextN) continue;
                int[] rec = dfs(nextN, aNext, bNext);
                earliest = Math.min(earliest, 1 + rec[0]);
                latest = Math.max(latest, 1 + rec[1]);
            }
        }

        int[] ans = new int[]{earliest, latest};
        memo.put(key, ans);
        return ans;
    }

    private int bucket(int idx, int a, int b) {
        if (idx < a) return 0;
        if (idx > b) return 2;
        // idx between a and b (but should not be equal to a or b for non-target)
        return 1;
    }
}

